import unittest
from slots import reserve
class TestSlots(unittest.TestCase):
    def test_new(self):self.assertEqual(reserve({},'S','A'),{'S':'A'})
    def test_duplicate(self):self.assertEqual(reserve({'S':'A'},'S','A'),{'S':'A'})
    def test_conflict(self):
        with self.assertRaises(ValueError):reserve({'S':'A'},'S','B')

